      r=run(d, f"{pname}/b5={b5}/extra={extra}")
      cnt+=1
      if r: found.append(r)
print("tested",cnt,"found",len(found))
for tag,rc,out in found[:10]:
    print("==== ",tag,"rc=",rc)
    print(out[:600])
