static int delp(void*p){ if(!p)return 1; unsigned i=h(p); while(live[i]){ if(live[i]==p){ live[i]=(void*)-1; return 1;} i=(i+1)&(CAP-1);} return 0; }
void free(void*p){ init(); if(p){ if(!delp(p)){ fprintf(stderr,"\n*** DOUBLE-FREE/INVALID-FREE ptr=%p ***\n",p); fflush(stderr); abort(); } } real_free(p);} 
void* malloc(size_t n){ init(); void*p=real_malloc(n); addp(p); return p; }
