static void* (*real_calloc)(size_t,size_t)=NULL;
static void* (*real_realloc)(void*,size_t)=NULL;
static char (*real_strdup)(const char*)=NULL;
#define CAP (1<<21)
#define EMPTY ((void*)0)
#define TOMB  ((void*)1)
static void* live[CAP];
static int inited=0;
static unsigned long dbl=0;
static unsigned h(void*p){unsigned long x=(unsigned long)p>>4; x^=x>>13; x^=x>>27; return (unsigned)(x&(CAP-1));}
static void init(){ if(!inited){ real_free=dlsym(RTLD_NEXT,"free"); real_malloc=dlsym(RTLD_NEXT,"malloc"); real_calloc=dlsym(RTLD_NEXT,"calloc"); real_realloc=dlsym(RTLD_NEXT,"realloc"); real_strdup=dlsym(RTLD_NEXT,"strdup"); memset(live,0,sizeof(live)); inited=1; } }
static void addp(void*p){ if(!p)return; unsigned i=h(p); while(live[i]!=EMPTY && live[i]!=TOMB && live[i]!=p) i=(i+1)&(CAP-1); live[i]=p; }
static int delp(void*p){ if(!p)return 1; unsigned i=h(p); while(live[i]!=EMPTY){ if(live[i]==p){ live[i]=TOMB; return 1;} i=(i+1)&(CAP-1);} return 0; }
void free(void*p){ init(); if(p){ if(!delp(p)){ dbl++; fprintf(stderr,"\n*** DOUBLE-FREE/INVALID ptr=%p count=%lu ***\n",p,dbl); fflush(stderr);} } real_free(p);} 
void* malloc(size_t n){ init(); void*p=real_malloc(n); addp(p); return p; }
void* calloc(size_t a,size_t b){ init(); void*p=real_calloc(a,b); addp(p); return p; }
void* realloc(void*p,size_t n){ init(); if(p) delp(p); void*q=real_realloc(p,n); if(q!=p) addp(q); else addp(q); return q; }
char* strdup(const char*s){ init(); char*p=real_strdup(s); addp(p); return p; }
__attribute__((destructor)) static void rep(){ if(dbl) fprintf(stderr,"\n*** TOTAL DOUBLE-FREES: %lu ***\n",dbl); }
EOF
