#define _GNU_SOURCE
#include <string.h>
#include <dlfcn.h>
#include <unistd.h>
#include <sys/mman.h>
#include <stdint.h>
#include <stdlib.h>
static void (*real_free)(void*)=NULL;
static void* (*real_malloc)(size_t)=NULL;
static void* (*real_calloc)(size_t,size_t)=NULL;
static void* (*real_realloc)(void*,size_t)=NULL;
#define CAP (1<<20)
static void** live=NULL;
static int ready=0;
static void real_init(void){
  if(ready) return;
  real_free=dlsym(RTLD_NEXT,"free"); real_malloc=dlsym(RTLD_NEXT,"malloc"); real_calloc=dlsym(RTLD_NEXT,"calloc"); real_realloc=dlsym(RTLD_NEXT,"realloc");
  live=mmap(NULL,CAP*sizeof(void*),PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0);
  ready=1;
}
static unsigned h(void*p){unsigned long x=(unsigned long)p>>4; x*=0x9E3779B97F4A7C15UL; x>>=40; return (unsigned)(x&(CAP-1));}
static void addp(void*p){ if(!p||!ready||!live||live==MAP_FAILED)return; live[h(p)]=p; }
static int delp(void*p){ if(!p||!ready||!live||live==MAP_FAILED)return 1; unsigned i=h(p); if(live[i]==p){ live[i]=0; return 1;} return 0; }
static void report(void*p){
  char b[40]; const char*m="\n*** DOUBLE-FREE ptr=0x"; int n=0,i;
  for(i=0;m[i];i++) b[n++]=m[i];
  for(i=15;i>=0;i--){ int d=(int)(((uintptr_t)p>>(i*4))&0xf); b[n++]= d<10?('0'+d):('a'+d-10); }
  b[n++]='\n'; if(write(2,b,n)<0){}
}
void free(void*p){ if(!ready) real_init(); if(p){ if(!delp(p)) report(p); } real_free(p);} 
void* malloc(size_t n){ if(!ready) real_init(); void*p=real_malloc(n); addp(p); return p; }
void* calloc(size_t a,size_t b){ if(!ready) real_init(); void*p=real_calloc(a,b); addp(p); return p; }
